#!/usr/bin/env python3
"""Generates the v59+ themes (Dusk, seasonal and meme looks) and writes them into index.html between the two marker comments.
Run it after editing a theme below:  python3 tools/gen-themes.py
It also checks WCAG contrast for every theme and refuses to write anything that falls short.
To add a theme: add an entry to THEMES, then add [key, label] to the THEMES list and the key to the applySkin() regex in index.html."""
import os, re, sys, urllib.parse
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
START, END = '/* ===== v59 themes: generated by tools/gen-themes.py, do not edit by hand ===== */', '/* ===== end v59 themes ===== */'

def lum(h):
    h = h.lstrip('#'); r, g, b = [int(h[i:i + 2], 16) / 255 for i in (0, 2, 4)]
    f = lambda c: c / 12.92 if c <= .03928 else ((c + .055) / 1.055) ** 2.4
    return .2126 * f(r) + .7152 * f(g) + .0722 * f(b)
def cr(a, b):
    la, lb = sorted([lum(a), lum(b)], reverse=True); return (la + .05) / (lb + .05)
def svg(s):
    return 'url("data:image/svg+xml,' + urllib.parse.quote(s, safe="/:=' ").replace('%20', ' ').replace('"', "'") + '")'

DARK = dict(blue='#8fbcf5', green='#9fdcb4', red='#f09a92', white='#eef0f6', silver='#c3cfdc', rose='#f0adc4', azure='#7fd0e6', prism='#bfb0f0', gold='#e8cf8c', purple='#b5a5ee', black='#d6dfea', warn='#e8c070', ok='#9fdcb4')
LIGHT = dict(blue='#2a67d8', green='#16805a', red='#c8344d', white='#7d86ab', silver='#5f6888', rose='#b8336f', azure='#137b9c', prism='#7a3cc0', gold='#8f6a0a', purple='#6a49c8', black='#2b2f45', warn='#a85b00', ok='#16805a')

dots = lambda col, n, w, h, rmax: ''.join("<circle cx='%d' cy='%d' r='%.1f' fill='%s' fill-opacity='%.2f'/>" % ((i * 53) % w, (i * 97) % h, 1 + (i % 3) * rmax / 3, col, .35 + (i % 4) * .15) for i in range(n))
leaf = lambda col, x, y, r: "<path transform='translate(%d %d) rotate(%d)' d='M0 0C6 -8 14 -6 16 0C14 8 6 10 0 0Z' fill='%s' fill-opacity='.55'/>" % (x, y, r, col)
paw = lambda col, x, y: "<g fill='%s' fill-opacity='.22' transform='translate(%d %d)'><ellipse cx='0' cy='4' rx='6' ry='5'/><circle cx='-7' cy='-4' r='2.6'/><circle cx='-2.5' cy='-8' r='2.6'/><circle cx='2.5' cy='-8' r='2.6'/><circle cx='7' cy='-4' r='2.6'/></g>" % (col, x, y)


def gear(col, cx, cy, r, op):
    teeth = ''.join("<rect x='%d' y='%d' width='%d' height='%d' transform='rotate(%d %d %d)'/>" % (cx - r // 6, cy - r - r // 4, r // 3, r // 2, a, cx, cy) for a in range(0, 360, 45))
    return "<g fill='%s' fill-opacity='%.2f'>%s<circle cx='%d' cy='%d' r='%d'/></g><circle cx='%d' cy='%d' r='%d' fill='none' stroke='#000' stroke-opacity='.35' stroke-width='3'/>" % (col, op, teeth, cx, cy, r, cx, cy, r // 2)
